:root {
  --bg1: #0f1020;
  --bg2: #1b1d3a;
  --panel: rgba(255, 255, 255, 0.06);
  --border: rgba(255, 255, 255, 0.12);
  --accent: #4fd1ff;
  --text: #e8ecff;
  --muted: #8b93c0;
}

html, body {
  height: 100%;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  font-family: "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  color: var(--text);
  background: radial-gradient(circle at 20% 10%, #23264d 0%, var(--bg1) 45%, #07070f 100%);
  padding: 20px;
  user-select: none;
}

.game-wrap {
  display: flex;
  gap: 22px;
  align-items: flex-start;
}

.board-area {
  position: relative;
  border-radius: 14px;
  padding: 10px;
  background: var(--panel);
  border: 1px solid var(--border);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.55), inset 0 0 40px rgba(79, 209, 255, 0.05);
}

#board {
  display: block;
  border-radius: 8px;
  background: #0a0b16;
}

.overlay {
  position: absolute;
  inset: 10px;
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  text-align: center;
  background: rgba(8, 9, 20, 0.82);
  backdrop-filter: blur(4px);
  transition: opacity 0.25s ease;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay h1 {
  font-size: 26px;
  letter-spacing: 2px;
  background: linear-gradient(90deg, #4fd1ff, #a78bfa, #ff7ab6);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.overlay p {
  color: var(--muted);
  font-size: 14px;
}

.overlay b { color: var(--accent); }

#overlay-btn {
  margin-top: 4px;
  padding: 10px 26px;
  font-size: 15px;
  font-weight: 600;
  color: #06121a;
  cursor: pointer;
  border: none;
  border-radius: 999px;
  background: linear-gradient(135deg, #4fd1ff, #7ef0c8);
  box-shadow: 0 8px 24px rgba(79, 209, 255, 0.35);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

#overlay-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 30px rgba(79, 209, 255, 0.5);
}

.side {
  display: flex;
  flex-direction: column;
  gap: 12px;
  width: 170px;
}

.panel {
  padding: 12px 14px;
  border-radius: 12px;
  background: var(--panel);
  border: 1px solid var(--border);
}

.label {
  font-size: 12px;
  letter-spacing: 1px;
  color: var(--muted);
  text-transform: uppercase;
  margin-bottom: 6px;
}

.value {
  font-size: 30px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--accent);
  text-shadow: 0 0 18px rgba(79, 209, 255, 0.4);
}

.value.small { font-size: 22px; color: var(--text); text-shadow: none; }

.next-panel { text-align: center; }

#next {
  display: block;
  margin: 0 auto;
  background: #0a0b16;
  border-radius: 8px;
}

.help ul {
  list-style: none;
  font-size: 12.5px;
  line-height: 1.9;
  color: var(--muted);
}

@media (max-width: 620px) {
  .game-wrap { flex-direction: column; align-items: center; }
  .side { width: 300px; flex-direction: row; flex-wrap: wrap; }
  .panel { flex: 1 1 40%; }
  .help { flex: 1 1 100%; }
}
